import re
with open("app.py", "r", encoding="utf-8") as f:
    c = f.read()

FAV = 'data:image/png;base64,'
fav_tag = '<link rel="icon" type="image/png" href="' + FAV + '"/>'
c = re.sub(r'<link rel="icon"[^>]*/>', fav_tag, c)
if 'rel="icon"' not in c:
    c = c.replace("<head>", "<head>\n  " + fav_tag, 1)
print("Favicon fixed!")

if "dl-bar" not in c:
    c = c.replace("</style>", '\n  .dl-bar{display:none;padding:8px 16px;background:#0d1117;border-top:1px solid #21262d;gap:8px;align-items:center;flex-wrap:wrap;}\n  .dl-bar.show{display:flex;}\n  .dl-btn{padding:7px 14px;border-radius:7px;cursor:pointer;font-size:0.8rem;font-weight:600;border:none;transition:all 0.2s;}\n  .dl-btn-pdf{background:linear-gradient(135deg,#34d399,#10b981);color:#0a1a0f;}\n  .dl-btn-txt{background:#1a3a2a;color:#34d399;border:1px solid #34d399;}\n  .dl-btn-copy{background:#1a1f2e;color:#60a5fa;border:1px solid #60a5fa;}\n  .dl-btn:hover{transform:translateY(-1px);}\n' + "</style>", 1)
    print("Download CSS added")

if "dl-bar" not in c:
    c = c.replace('<div class="terminal"', '\n<div class="dl-bar" id="dl-bar"><span style="color:#34d399;font-size:0.8rem;font-weight:600;">&#9660; Download Report:</span><button class="dl-btn dl-btn-pdf" onclick="dlPDF()">&#128196; PDF</button><button class="dl-btn dl-btn-txt" onclick="dlTXT()">&#128196; Text</button><button class="dl-btn dl-btn-copy" onclick="dlCopy()">&#128203; Copy</button></div>\n' + '<div class="terminal"', 1)
    print("Download bar HTML added")

if "dlPDF" not in c:
    c = c.replace("</body>", "<script>" + '\nfunction dlTXT(){var t=document.getElementById("terminal");var txt=t?t.innerText:"";var b=new Blob([txt],{type:"text/plain"});var a=document.createElement("a");a.href=URL.createObjectURL(b);a.download="GreenOps_Report_"+new Date().toISOString().split("T")[0]+".txt";a.click();}\nfunction dlPDF(){var t=document.getElementById("terminal");var txt=t?t.innerText:"";var w=window.open("","_blank");w.document.write("<html><head><title>GreenOps Report</title><style>body{font-family:monospace;background:#0d1117;color:#c9d1d9;padding:40px;white-space:pre-wrap;line-height:1.6;}h2{color:#34d399;}</style></head><body><h2>&#127807; GreenOps AI Report - "+new Date().toLocaleDateString()+"</h2><pre>"+txt.replace(/</g,"&lt;").replace(/>/g,"&gt;")+"</pre></body></html>");w.document.close();setTimeout(function(){w.print();},500);}\nfunction dlCopy(){var t=document.getElementById("terminal");var txt=t?t.innerText:"";navigator.clipboard.writeText(txt).then(function(){var b=document.querySelector(".dl-btn-copy");if(b){b.textContent="Copied!";setTimeout(function(){b.innerHTML="&#128203; Copy";},2000);}});}\nfunction showDlBar(){var b=document.getElementById("dl-bar");if(b)b.classList.add("show");}\n' + "</script>\n</body>", 1)
    print("Download JS added")

if "showDlBar" not in c:
    c = c.replace("setStatus('done'", "showDlBar(); setStatus('done'", 1)
    print("Download bar hooked to pipeline done")

with open("app.py", "w", encoding="utf-8") as f:
    f.write(c)
print("ALL DONE!")
